import { useEffect, useRef } from "react";

/* ──────────────────────────────────────────────────────────────────────────
   ADHD Daily — logo animato su <canvas>

   Fedeltà: le quattro forme (ciottoli + sfera) e le tre scritte sono ritagliate
   pixel per pixel dalla tua immagine originale (sprite WebP con trasparenza, 2x)
   e disegnate sul canvas. Nessuna forma è ridisegnata a mano.

   Uso:  <AdhdDailyLogo />
   Props: autoPlay (true), replayOnClick (true), transparent (false),
          onComplete, className, style
   ────────────────────────────────────────────────────────────────────────── */

// Sprite: coordinate (x, y, w, h) nel sistema dell'immagine originale (723×560)
const SPRITES = {"sopra":{"src":"data:image/webp;base64,","x":291,"y":21,"w":138,"h":90},"sfera":{"src":"data:image/webp;base64,","x":447,"y":49,"w":96,"h":91},"mezzo":{"src":"data:image/webp;base64,","x":227,"y":108,"w":261,"h":137},"sotto":{"src":"data:image/webp;base64,","x":160,"y":214,"w":381,"h":155},"adhd":{"src":"data:image/webp;base64,","x":87,"y":392,"w":325,"h":109},"daily":{"src":"data:image/webp;base64,","x":440,"y":392,"w":213,"h":109},"tagline":{"src":"data:image/webp;base64,","x":104,"y":512,"w":522,"h":29}};

// ── Spazio logico del canvas ────────────────────────────────────────────────
const W = 1100;
const H = 520;

// ── Geometria nell'immagine originale ───────────────────────────────────────
const LOGO_C = { x: 352.5, y: 194.5 };      // centro del logo (ciottoli + sfera)
const LOGO_W = 365;                          // larghezza del logo (170 → 535)
const TEXT_X0 = 93;                          // inizio scritta "ADHD"
const TEXT_W = 553;                          // larghezza titolo (93 → 646)
const TEXT_CY = 466;                         // centro verticale blocco testo
const PIVOT = {                              // punto di appoggio per lo "schiacciamento"
  sotto: { x: 350, y: 352 },
  mezzo: { x: 357, y: 232 },
  sopra: { x: 360, y: 100 },
};
const SPHERE_REST = { x: 495, y: 94.5 };    // posizione finale della sfera
const ORBIT_C = { x: 357, y: 150 };          // centro dell'orbita della sfera
const TH_R = -0.5;                           // angolo di arrivo sull'orbita
const ORBIT_A = (SPHERE_REST.x - ORBIT_C.x) / Math.cos(TH_R);
const ORBIT_B = (SPHERE_REST.y - ORBIT_C.y) / Math.sin(TH_R);
const ORBIT_TURNS = 1.25;                    // giri compiuti dalla sfera

// ── Impaginazione finale: logo a sinistra, scritte a destra ─────────────────
const LOCKUP = (() => {
  const logoScale = 0.92;
  const textScale = 1;
  const gap = 70;
  const logoW = LOGO_W * logoScale;
  const textW = TEXT_W * textScale;
  const left = (W - (logoW + gap + textW)) / 2;
  return {
    logoScale,
    textScale,
    logoX: left + logoW / 2,
    logoY: H / 2,
    textDX: left + logoW + gap - TEXT_X0 * textScale,
    textDY: H / 2 - TEXT_CY * textScale,
  };
})();
const INTRO_SCALE = 1.05; // il logo parte centrato, un po' più grande

// ── Timeline (secondi) ──────────────────────────────────────────────────────
const T = {
  sotto: [0.25, 0.8],
  mezzo: [0.65, 0.75],
  sopra: [1.0, 0.75],
  sfera: [1.7, 2.2],       // [inizio, durata] dell'orbita
  shift: [3.9, 1.1],       // il logo scivola a sinistra
  adhd: [4.15, 0.95],
  daily: [4.45, 0.9],
  tagline: [5.0, 0.8],
  end: 5.9,
  idle: 5.3,               // da qui in poi: leggera fluttuazione continua
};

// ── Utilità ─────────────────────────────────────────────────────────────────
const clamp01 = (v) => Math.min(1, Math.max(0, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (t) => {
  t = clamp01(t);
  return t * t * (3 - 2 * t);
};
const easeOutCubic = (t) => 1 - Math.pow(1 - clamp01(t), 3);
const easeInOutCubic = (t) => {
  t = clamp01(t);
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
};
const easeOutBack = (t) => {
  t = clamp01(t);
  const c1 = 1.4;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};
const prog = (t, [t0, d]) => clamp01((t - t0) / d);
// oscillazione smorzata quando un ciottolo "atterra"
const impulse = (t, tl) =>
  t > tl ? Math.exp(-(t - tl) * 6.5) * Math.sin((t - tl) * 16) : 0;

// ── Posizione della sfera lungo l'orbita ────────────────────────────────────
function spherePath(u) {
  const e = easeOutCubic(u);
  const th = TH_R - (1 - e) * ORBIT_TURNS * Math.PI * 2;
  const m = 0.55 + 0.45 * e; // la spirale si allarga fino alla posizione finale
  const s = Math.sin(th);
  return {
    x: ORBIT_C.x + m * ORBIT_A * Math.cos(th),
    y: ORBIT_C.y + m * ORBIT_B * s,
    // sin > 0: lato anteriore dell'orbita (davanti ai ciottoli)
    front: s > 0,
    scale: 1 + 0.22 * (s - Math.sin(TH_R)) * Math.sqrt(1 - e),
  };
}

export default function AdhdDailyLogo({
  autoPlay = true,
  replayOnClick = true,
  transparent = false,
  onComplete,
  className,
  style,
}) {
  const canvasRef = useRef(null);
  const startRef = useRef(0);
  const doneRef = useRef(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const ctx = canvas.getContext("2d");
    const reduced =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let raf = 0;
    let alive = true;
    const imgs = {};
    const scratch = document.createElement("canvas");
    const sctx = scratch.getContext("2d");

    // ── ridimensionamento (nitido su schermi retina) ──
    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2.5);
      const cssW = canvas.clientWidth || W;
      canvas.width = Math.round(cssW * dpr);
      canvas.height = Math.round((cssW * dpr * H) / W);
    };
    const ro = new ResizeObserver(resize);
    ro.observe(canvas);
    resize();

    // ── sprite del logo con "reveal" a bordo morbido (per le scritte) ──
    const drawReveal = (img, m, p, alpha) => {
      if (p <= 0 || alpha <= 0) return;
      if (p >= 1) {
        ctx.globalAlpha = alpha;
        ctx.drawImage(img, m.x, m.y, m.w, m.h);
        ctx.globalAlpha = 1;
        return;
      }
      const iw = img.naturalWidth;
      const ih = img.naturalHeight;
      if (scratch.width !== iw || scratch.height !== ih) {
        scratch.width = iw;
        scratch.height = ih;
      }
      const soft = 0.22;
      const edge = p * (1 + soft);
      sctx.globalCompositeOperation = "source-over";
      sctx.clearRect(0, 0, iw, ih);
      sctx.drawImage(img, 0, 0);
      sctx.globalCompositeOperation = "destination-in";
      const g = sctx.createLinearGradient((edge - soft) * iw, 0, edge * iw, 0);
      g.addColorStop(0, "rgba(0,0,0,1)");
      g.addColorStop(1, "rgba(0,0,0,0)");
      sctx.fillStyle = g;
      sctx.fillRect(0, 0, iw, ih);
      ctx.globalAlpha = alpha;
      ctx.drawImage(scratch, m.x, m.y, m.w, m.h);
      ctx.globalAlpha = 1;
    };

    // ── un ciottolo con trasformazioni attorno al suo punto di appoggio ──
    const drawStone = (name, st) => {
      if (st.alpha <= 0) return;
      const m = SPRITES[name];
      const pv = PIVOT[name];
      ctx.save();
      ctx.translate(pv.x + st.dx, pv.y + st.dy);
      ctx.rotate(st.rot);
      ctx.scale(st.sx, st.sy);
      ctx.translate(-pv.x, -pv.y);
      ctx.globalAlpha = st.alpha;
      ctx.drawImage(imgs[name], m.x, m.y, m.w, m.h);
      ctx.restore();
    };

    const drawSphere = (x, y, s, alpha, additive) => {
      if (alpha <= 0) return;
      const m = SPRITES.sfera;
      ctx.save();
      ctx.globalCompositeOperation = additive ? "lighter" : "source-over";
      ctx.globalAlpha = alpha;
      ctx.translate(x, y);
      ctx.scale(s, s);
      ctx.drawImage(imgs.sfera, m.x - SPHERE_REST.x, m.y - SPHERE_REST.y, m.w, m.h);
      ctx.restore();
    };

    const render = (t, withIdle) => {
      const k = canvas.width / W;
      ctx.setTransform(k, 0, 0, k, 0, 0);
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.clearRect(0, 0, W, H);

      // sfondo: gradiente campionato dall'immagine originale
      if (!transparent) {
        const bg = ctx.createRadialGradient(0, 0, 0, 0, 0, Math.hypot(W, H));
        bg.addColorStop(0, "#072443");
        bg.addColorStop(0.35, "#021a39");
        bg.addColorStop(0.8, "#011226");
        bg.addColorStop(1, "#001125");
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, W, H);
      }

      const idle = withIdle ? smooth((t - T.idle) / 1.2) : 0;

      // ── posizione/scala del gruppo logo ──
      const g = easeInOutCubic(prog(t, T.shift));
      const gx = lerp(W / 2, LOCKUP.logoX, g);
      const gy = lerp(H / 2, LOCKUP.logoY, g);
      const gs = lerp(INTRO_SCALE, LOCKUP.logoScale, g);

      // alone morbido dietro al logo
      const haloPulse = 0.14 + 0.04 * Math.sin(t * 1.2) * (withIdle ? 1 : 0);
      const halo = ctx.createRadialGradient(gx, gy, 0, gx, gy, 360 * gs);
      halo.addColorStop(0, `rgba(56,110,196,${haloPulse * smooth(t / 0.9)})`);
      halo.addColorStop(1, "rgba(56,110,196,0)");
      ctx.fillStyle = halo;
      ctx.fillRect(0, 0, W, H);

      // ── stato dei ciottoli ──
      const uS = prog(t, T.sotto);
      const uM = prog(t, T.mezzo);
      const uP = prog(t, T.sopra);
      const Lm = impulse(t, T.mezzo[0] + T.mezzo[1]);
      const Ls = impulse(t, T.sopra[0] + T.sopra[1]);
      const eS = easeOutCubic(uS);
      const eM = easeOutCubic(uM);
      const eP = easeOutCubic(uP);

      const sotto = {
        dx: 0,
        dy: 70 * (1 - eS) + idle * 1.2 * Math.sin(t * 0.9),
        rot: 0,
        sx: (0.9 + 0.1 * eS) * (1 + 0.02 * (Lm + Ls)),
        sy: (0.9 + 0.1 * eS) * (1 - 0.035 * Lm - 0.02 * Ls),
        alpha: smooth(uS / 0.5),
      };
      const dropSotto = 135 * (0.035 * Lm + 0.02 * Ls);
      const mezzo = {
        dx: 0,
        dy: -90 * (1 - eM) + dropSotto + idle * 1.8 * Math.sin(t * 0.9 + 1.1),
        rot: 0,
        sx: 1 + 0.03 * Lm + 0.02 * Ls,
        sy: 1 - 0.05 * Lm - 0.03 * Ls,
        alpha: smooth(uM / 0.4),
      };
      const dropMezzo = 114 * (0.05 * Lm + 0.03 * Ls);
      const sopra = {
        dx: 0,
        dy: -110 * (1 - eP) + dropSotto + dropMezzo + idle * 2.6 * Math.sin(t * 0.9 + 2.2),
        rot: -0.12 * (1 - eP),
        sx: 1 + 0.04 * Ls,
        sy: 1 - 0.06 * Ls,
        alpha: smooth(uP / 0.4),
      };

      // ── stato della sfera ──
      const uO = prog(t, T.sfera);
      const sphereIn = smooth((t - T.sfera[0]) / 0.28);
      const orbitOn = uO > 0 && uO < 1;
      const p = spherePath(uO);
      let sx = p.x;
      let sy = p.y;
      let ss = p.scale * (0.4 + 0.6 * easeOutBack(sphereIn));
      if (uO >= 1) {
        sx = SPHERE_REST.x + idle * (Math.cos(t * 0.75) * 6);
        sy = SPHERE_REST.y + idle * (Math.sin(t * 1.15) * 7);
        ss = 1;
      }
      const sphereAlpha = sphereIn;
      const sphereGlow = 0.12 + 0.2 * (1 - easeInOutCubic(uO)) * (uO > 0 ? 1 : 0) +
        0.04 * Math.sin(t * 2.1) * idle;

      const drawSphereLayer = () => {
        if (sphereAlpha <= 0) return;
        // scia luminosa
        if (orbitOn) {
          for (let i = 10; i >= 1; i -= 1) {
            const q = spherePath(Math.max(0, uO - i * 0.011));
            drawSphere(q.x, q.y, ss * (1 - i * 0.04), 0.3 * (1 - i / 11), true);
          }
        }
        // bagliore caldo attorno
        const r = 80 * ss;
        const gl = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
        gl.addColorStop(0, `rgba(255,214,176,${sphereGlow * sphereAlpha})`);
        gl.addColorStop(1, "rgba(255,214,176,0)");
        ctx.save();
        ctx.globalCompositeOperation = "lighter";
        ctx.fillStyle = gl;
        ctx.fillRect(sx - r, sy - r, r * 2, r * 2);
        ctx.restore();
        drawSphere(sx, sy, ss, sphereAlpha, false);
      };

      // ── gruppo logo ──
      ctx.save();
      ctx.translate(gx, gy);
      ctx.scale(gs, gs);
      ctx.translate(-LOGO_C.x, -LOGO_C.y);

      const behind = orbitOn && !p.front;
      if (behind) drawSphereLayer();
      drawStone("sotto", sotto);
      drawStone("mezzo", mezzo);
      drawStone("sopra", sopra);
      if (!behind) drawSphereLayer();
      ctx.restore();

      // ── scritte a destra ──
      ctx.save();
      ctx.translate(LOCKUP.textDX, LOCKUP.textDY);
      ctx.scale(LOCKUP.textScale, LOCKUP.textScale);

      const pa = prog(t, T.adhd);
      ctx.save();
      ctx.translate(-40 * (1 - easeOutCubic(pa)), 0);
      drawReveal(imgs.adhd, SPRITES.adhd, easeInOutCubic(pa), smooth(pa / 0.3));
      ctx.restore();

      const pd = prog(t, T.daily);
      ctx.save();
      ctx.translate(-40 * (1 - easeOutCubic(pd)), 0);
      drawReveal(imgs.daily, SPRITES.daily, easeInOutCubic(pd), smooth(pd / 0.3));
      ctx.restore();

      const pt = prog(t, T.tagline);
      ctx.save();
      ctx.translate(-24 * (1 - easeOutCubic(pt)), 0);
      drawReveal(imgs.tagline, SPRITES.tagline, easeInOutCubic(pt), smooth(pt / 0.3));
      ctx.restore();

      ctx.restore();
    };

    // ── caricamento sprite e avvio ──
    const names = Object.keys(SPRITES);
    Promise.all(
      names.map(
        (n) =>
          new Promise((resolve, reject) => {
            const im = new Image();
            im.onload = () => {
              imgs[n] = im;
              resolve();
            };
            im.onerror = reject;
            im.src = SPRITES[n].src;
          })
      )
    )
      .then(() => {
        if (!alive) return;
        if (reduced || !autoPlay) {
          render(T.end, false); // fotogramma finale statico
          return;
        }
        startRef.current = performance.now();
        const tick = (now) => {
          const t = (now - startRef.current) / 1000;
          render(t, true);
          if (t >= T.end && !doneRef.current) {
            doneRef.current = true;
            if (onComplete) onComplete();
          }
          raf = requestAnimationFrame(tick);
        };
        raf = requestAnimationFrame(tick);
      })
      .catch(() => {});

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      ro.disconnect();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPlay, transparent]);

  const replay = () => {
    startRef.current = performance.now();
    doneRef.current = false;
  };

  return (
    <canvas
      ref={canvasRef}
      role="img"
      aria-label="ADHD Daily — il tuo spazio mentale"
      onClick={replayOnClick ? replay : undefined}
      className={className}
      style={{
        width: "100%",
        height: "auto",
        aspectRatio: `${W} / ${H}`,
        display: "block",
        cursor: replayOnClick ? "pointer" : "default",
        ...style,
      }}
    />
  );
}
